#include "runner.hpp"
#include <fstream>
#include <iostream>
#include <sstream>
#include <algorithm>
struct Det { float x,y,w,h,q; };
static float iou(const Det&a,const Det&b){float x1=std::max(a.x-a.w/2,b.x-b.w/2),y1=std::max(a.y-a.h/2,b.y-b.h/2),x2=std::min(a.x+a.w/2,b.x+b.w/2),y2=std::min(a.y+a.h/2,b.y+b.h/2);float inter=std::max(0.f,x2-x1)*std::max(0.f,y2-y1);return inter/(a.w*a.h+b.w*b.h-inter+1e-6f);}
class Logger:public nvinfer1::ILogger{void log(Severity s,const char* m)noexcept override{if(s<=Severity::kWARNING)std::cerr<<m<<'\n';}};static Logger logger;
Runner::Runner(const std::string&p){std::ifstream f(p,std::ios::binary);std::vector<char>b((std::istreambuf_iterator<char>(f)),{});runtime_=nvinfer1::createInferRuntime(logger);engine_=runtime_->deserializeCudaEngine(b.data(),b.size());context_=engine_->createExecutionContext();auto s=engine_->getTensorShape("images");width_=s.d[3];height_=s.d[2];cudaStreamCreate(&stream_);cudaMalloc(&input_,3*width_*height_*4);cudaMalloc(&output_,37*8400*4);cudaMalloc(&proto_,32*160*160*4);}
Runner::~Runner(){cudaFree(input_);cudaFree(output_);cudaFree(proto_);if(stream_)cudaStreamDestroy(stream_);delete context_;delete engine_;delete runtime_;}
std::string Runner::infer(const std::vector<unsigned char>&b){cv::Mat src=cv::imdecode(b,cv::IMREAD_COLOR);if(src.empty())return"{\"predictions\":[],\"image\":{\"width\":0,\"height\":0}}";cv::Mat img;cv::resize(src,img,cv::Size(width_,height_));std::vector<float>h(3*width_*height_);for(int y=0;y<height_;++y)for(int x=0;x<width_;++x){auto p=img.at<cv::Vec3b>(y,x);for(int c=0;c<3;++c)h[c*width_*height_+y*width_+x]=p[2-c]/255.f;}cudaMemcpyAsync(input_,h.data(),h.size()*4,cudaMemcpyHostToDevice,stream_);context_->setTensorAddress("images",input_);context_->setTensorAddress("output0",output_);context_->setTensorAddress("output1",proto_);if(!context_->enqueueV3(stream_))return"{\"predictions\":[],\"error\":\"enqueue_failed\"}";std::vector<float>o(37*8400);cudaMemcpyAsync(o.data(),output_,o.size()*4,cudaMemcpyDeviceToHost,stream_);cudaStreamSynchronize(stream_);float sx=src.cols/(float)width_,sy=src.rows/(float)height_;std::vector<Det>d;for(int i=0;i<8400;++i){float q=o[4*8400+i];if(q>=.35f)d.push_back({o[i]*sx,o[8400+i]*sy,o[2*8400+i]*sx,o[3*8400+i]*sy,q});}std::sort(d.begin(),d.end(),[](auto&a,auto&b){return a.q>b.q;});std::vector<Det>keep;for(auto&v:d){bool drop=false;for(auto&k:keep)if(iou(v,k)>.45f){drop=true;break;}if(!drop)keep.push_back(v);}std::ostringstream j;j<<"{\"predictions\":[";for(size_t i=0;i<keep.size();++i){if(i)j<<',';auto&v=keep[i];j<<"{\"x\":"<<v.x<<",\"y\":"<<v.y<<",\"width\":"<<v.w<<",\"height\":"<<v.h<<",\"confidence\":"<<v.q<<",\"class\":\"plate\",\"class_id\":0,\"points\":[]}";}j<<"],\"image\":{\"width\":"<<src.cols<<",\"height\":"<<src.rows<<"}}";return j.str();}
